VIEWS.profissionais=()=>{clFala('profissionais',153,'Profissionais: cada um com conselho, agenda e repasse. O repasse certo é o único elogio que todo médico entende.');
 const esp=[...new Set(PROFISSIONAIS.map(p=>p.esp))];const l=PROFISSIONAIS.filter(p=>(!PRF_ESP||p.esp===PRF_ESP)&&(!PRF_Q||semAc(p.n+' '+p.cons+' '+p.esp).includes(semAc(PRF_Q))));
 return `${pageHead('Cadastros','Profissionais','Médicos, ultrassonografistas, enfermagem e responsáveis técnicos: conselho, especialidade, unidades, grade da agenda, o que fazem e o repasse. Dados de exemplo.',`${rulesBtn('Profissionais')}<button class="btn" onclick="clPrfForm()" ${tipAttr('Novo profissional','Nome, conselho com número e UF, especialidade, unidades, grade da agenda e regra de repasse.')}>${I.plus} Novo profissional</button>`)}
<div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Nome, conselho ou especialidade" value="${esc(PRF_Q)}" oninput="PRF_Q=this.value;$('#prfBody').innerHTML=clPrfRows()" aria-label="Buscar profissional"></div><select class="in" style="width:auto" onchange="PRF_ESP=this.value;reView()" aria-label="Especialidade"><option value="">Todas as especialidades</option>${esp.map(e=>`<option ${PRF_ESP===e?'selected':''}>${e}</option>`).join('')}</select></div>
<div class="tablewrap"><table class="at-table"><thead><tr><th>Profissional</th><th>Conselho</th><th>Especialidade</th><th>Unidades</th><th>Hoje</th><th>Repasse</th><th>Situação</th></tr></thead><tbody id="prfBody">${clPrfRows(l)}</tbody></table></div>
${piada(154,{admin:'Profissional sem conselho cadastrado não assina nada. Nem a ata da reunião.',medico:'Sua grade de agenda mora aqui. Quem mexe nela é a gestão; quem sofre com ela é você.',todos:'Um profissional, uma ficha: atende na clínica, lauda a imagem e assina o laboratório sem trocar de sistema.'})}`};
function clPrfRows(l){l=l||PROFISSIONAIS.filter(p=>(!PRF_ESP||p.esp===PRF_ESP)&&(!PRF_Q||semAc(p.n+' '+p.cons+' '+p.esp).includes(semAc(PRF_Q))));if(!l.length)return vazioLinha(7,'Ninguém encontrado','Mude a busca ou a especialidade.');
 return l.map(p=>`<tr style="cursor:pointer" onclick="clPrfVer('${p.id}')">${td('Profissional',`<div class="cx-user"><span class="avatar" style="background:${p.cor}">${p.ini}</span><div class="two">${esc(p.n)}<small>${(CL_GRADE[p.id]||[]).length} turnos na grade</small></div></div>`)}${td('Conselho',`<span class="mono">${esc(p.cons)}</span>`)}${td('Especialidade',esc(p.esp))}${td('Unidades',p.unids.map(u=>u===10?'Central':'Posto '+u).join(', '))}${td('Hoje',clAgHoje(p.id)+' na agenda')}${td('Repasse',esc(p.repasse))}${td('Situação',sitBadge(p.ativo))}</tr>`).join('')}
function clPrfVer(id,aba){const p=PROF(id);if(!p)return;PRF_ABA=aba||'dados';const procs=PROCEDIMENTOS.filter(x=>id==='p2'?x.tipo==='Imagem':id==='p4'?['10101012','10101039','40101010'].includes(x.c):id==='p3'?['10101012','10101039','40901530','30101921'].includes(x.c):id==='p6'?['20104090','20104138'].includes(x.c):id==='p1'?['10101012','10101039','20104138'].includes(x.c):false);
 const ag=[...AG_CLIN.filter(a=>a.prof===id).map(a=>({h:a.h,pac:a.pac,it:a.proc,sit:a.sit})),...CL_AG_EXTRA.filter(a=>a.prof===id).map(a=>({h:a.h,pac:a.pac,it:a.itens[0],sit:a.sit}))].sort((a,b)=>a.h.localeCompare(b.h));
 const abas=[['dados','Dados'],['grade','Grade da agenda'],['procs','O que faz'],['repasse','Repasse']];
 const corpo=PRF_ABA==='dados'?kvs([['Nome',esc(p.n)],['Conselho',`<span class="mono">${esc(p.cons)}</span> ${info('Conselho, número e UF: obrigatórios para assinar prontuário, laudo e receita.')}`],['Especialidade',esc(p.esp)],['Unidades',p.unids.map(unidNome).join('<br>')],['Assinatura','ICP-Brasil em nuvem · válida até 03/2027'],['Usuário do sistema',id==='p5'?'Dra. Helena Brito (perfil Dr.)':id==='p6'?'Tatiane Lopes (perfil Enfermagem)':id==='p2'?'Paulo Viana (perfil Médico de imagem)':'perfil Médico'],['Hoje',ag.length?ag.map(a=>`${a.h} · ${esc(a.pac.split(' ')[0])} · ${clProcNome(a.it)}`).join('<br>'):'sem agenda hoje']])
 :PRF_ABA==='grade'?`${tabela(['Dias','Horário','Sala','Duração'],(CL_GRADE[id]||[]).map(g=>`<tr>${g.map((v,j)=>td(['Dias','Horário','Sala','Duração'][j],esc(v))).join('')}</tr>`),'Sem grade')}<p class="tl" style="margin-top:8px">A grade gera os horários da Agenda. Férias e congressos entram como bloqueio; encaixe fora da grade só com permissão.</p><button class="btn sm sec" onclick="toast('Bloqueio de agenda: escolha o período e o motivo (férias, congresso). Pacientes marcados recebem aviso para remarcar.')">Bloquear período</button>`
 :PRF_ABA==='procs'?(procs.length?tabela(['Código TUSS','Procedimento','Duração'],procs.map(x=>`<tr>${td('Código TUSS',`<span class="mono">${x.c}</span>`)}${td('Procedimento',esc(x.n))}${td('Duração',x.dur+' min')}</tr>`)):'<p class="tl">Responsável técnica do laboratório: assina os resultados liberados na Conferência.</p>')
 :kvs([['Regra',esc(p.repasse)],['Outubro',p.repasse==='salário'?'—':fmt({p1:6840,p2:4185,p3:5520,p4:7210}[id]||0)+' · 3 dias para conferir'],['Quando paga','dia 10, depois do recebimento do convênio'],['Extrato','o profissional vê o próprio extrato no Repasse médico']]);
 openDrawer(esc(p.n),`<div class="tabs" role="tablist" style="flex-wrap:wrap">${abas.map(([k,t])=>`<button class="tab ${PRF_ABA===k?'active':''}" onclick="clPrfVer('${id}','${k}')">${t}</button>`).join('')}</div><div style="margin-top:10px">${corpo}</div><div class="row" style="margin-top:12px"><button class="btn sec" onclick="clPrfForm('${id}')">Editar</button><button class="btn ghost" onclick="closeDrawer();location.hash='#agenda'">Ver na agenda</button>${p.repasse!=='salário'?`<button class="btn ghost" onclick="closeDrawer();location.hash='#repasse'">Repasse médico</button>`:''}</div>`)}
function clPrfForm(id){const p=PROF(id)||{n:'',cons:'',esp:'',unids:[10],repasse:''};openModal(`${mh(id?'Editar profissional':'Novo profissional')}<div class="mb"><div class="formgrid"><div class="field"><label>Nome completo <span class="req">*</span></label><input class="in" value="${esc(p.n)}"></div><div class="field"><label>Conselho <span class="req">*</span></label><select class="in">${['CRM','CRBM','COREN','CRF','CRN','CREFITO','CRP'].map(c=>`<option ${(p.cons||'').startsWith(c)?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Número e UF <span class="req">*</span></label><input class="in" value="${esc((p.cons||'').replace(/^\S+\s?/,''))}" placeholder="CE 12.345"></div><div class="field"><label>Especialidade (CBO) <span class="req">*</span></label><input class="in" value="${esc(p.esp)}" placeholder="Ex.: Cardiologia"></div><div class="field"><label>Regra de repasse ${info('Percentual por particular ou convênio, valor fixo por procedimento ou salário. Entra no Repasse médico e no custo direto do procedimento.')}</label><input class="in" value="${esc(p.repasse)}" placeholder="60% particular · 70% convênio"></div><div class="field"><label>Cor na agenda</label><input class="in" type="color" value="${p.cor||'#23756D'}"></div></div><h4 style="margin-top:10px">Unidades</h4><div class="row">${[10,12,14].map(u=>`<label class="check"><input type="checkbox" ${p.unids.includes(u)?'checked':''}>${unidNome(u).split(' · ')[0]}</label>`).join('')}</div><p class="tl">O profissional pode ser ligado a um usuário (perfil Médico, Médico de imagem ou Enfermagem) para assinar no prontuário.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Profissional salvo','A grade da agenda e os procedimentos que ele faz ficam na ficha. Tudo vai para a auditoria.')">Salvar</button></div>`)}
GUIDES.profissionais=['Busque pelo nome, conselho ou especialidade.','Clique no profissional para ver a grade da agenda, o que ele faz e a regra de repasse.','Novo profissional pede conselho com número e UF; sem conselho, não assina prontuário nem laudo.'];
REGRAS['Profissionais']={aba:'Cadastros · Profissionais',itens:[['Conselho','Conselho, número e UF obrigatórios; sem eles não assina prontuário, receita nem laudo.'],['Um cadastro','O mesmo profissional atende na clínica, lauda a imagem e assina o laboratório; um só cadastro, ligado ao usuário.'],['Grade','A grade semanal (dias, horários, sala, duração) gera a agenda; bloqueios por período com motivo; encaixe fora da grade só com permissão.'],['Repasse','Percentual por particular e convênio, valor por procedimento ou salário; entra no custo direto e no Repasse médico.'],['Unidades','O profissional só aparece na agenda das unidades ligadas a ele.']]};

