function clAdmitir(id,pac){const livres=CL_LEITOS.filter(l=>l.sit==='livre'||l.id===id);openModal(`${mh('Admitir paciente')}<div class="mb"><div class="formgrid"><div class="field"><label>Paciente <span class="req">*</span> ${info('Cadastro único: o mesmo da clínica e do laboratório. Sem cadastro, faça pelo CPF em Pacientes.')}</label><select class="in" id="admPac">${PACIENTES.filter(p=>p.ativo&&!CL_LEITOS.some(l=>l.pac===p.n&&l.sit==='ocupado')).map(p=>`<option ${p.n===pac?'selected':''}>${esc(p.n)}</option>`).join('')}</select></div><div class="field"><label>Leito <span class="req">*</span></label><select class="in" id="admLeito">${livres.map(l=>`<option value="${l.id}" ${l.id===id?'selected':''}>${l.id} · ${l.ala}</option>`).join('')}</select></div><div class="field"><label>Médico responsável <span class="req">*</span></label><select class="in" id="admMed">${PROFISSIONAIS.filter(p=>/^Dr/.test(p.n)&&p.id!=='p5').map(p=>`<option value="${p.id}">${esc(p.n)}</option>`).join('')}</select></div><div class="field"><label>Diagnóstico (CID-10) <span class="req">*</span></label><input class="in" id="admDiag" placeholder="Ex.: J18.9 Pneumonia não especificada"></div><div class="field"><label>Convênio</label><select class="in" id="admConv"><option>Particular</option>${CONVENIOS.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label>Caráter</label><select class="in"><option>Eletiva</option><option>Urgência</option></select></div></div><p class="tl">No convênio, a guia de internação vai para autorização (TISS). A conta abre na admissão.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="clAdmitirOk()">Admitir</button></div>`)}
function clAdmitirOk(){const id=$('#admLeito').value,d=($('#admDiag').value||'').trim();if(!id){toast('Não há leito livre','warn');return}if(!d){toast('Informe o diagnóstico','warn');return}const l=CL_LEITOS.find(x=>x.id===id);Object.assign(l,{sit:'ocupado',pac:$('#admPac').value,adm:'2026-11-04',med:$('#admMed').value,diag:d,conv:$('#admConv').value,prev:'a definir',res:''});closeModal();closeDrawer();reView();retorno('ok','Paciente admitido no leito '+id,'A conta foi aberta e a prescrição hospitalar já pode ser feita no prontuário.',[{l:'Prescrever no prontuário',on:"location.hash='#atendimento-medico'"},{l:'Fechar',sec:true}])}
function clAlta(id){const l=CL_LEITOS.find(x=>x.id===id);openModal(`${mh('Alta · '+esc(l.pac))}<div class="mb"><div class="field"><label>Tipo de alta <span class="req">*</span></label><select class="in"><option>Melhorada</option><option>Curada</option><option>A pedido</option><option>Transferência para outro serviço</option><option>Óbito</option></select></div><div class="field"><label>Resumo de alta <span class="req">*</span> ${info('Vai para o prontuário e para o paciente, com as orientações e as receitas.')}</label><textarea class="in" rows="3" style="height:auto" id="altaRes">Evoluiu bem, afebril há 48 h. Orientado retorno em 7 dias no consultório.</textarea></div><label class="check"><input type="checkbox" checked>Agendar retorno no consultório</label><label class="check"><input type="checkbox" checked>Fechar a conta e mandar para o faturamento</label></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="clAltaOk('${id}')">Dar alta</button></div>`)}
function clAltaOk(id){if(!($('#altaRes').value||'').trim()){toast('Escreva o resumo de alta','warn');return}const l=CL_LEITOS.find(x=>x.id===id),n=l.pac;Object.assign(l,{sit:'higienizacao',desde:hhmm(new Date()),pac:'',alerta:''});closeModal();closeDrawer();reView();retorno('ok','Alta registrada',`${n.split(' ')[0]} teve alta. O leito ${id} foi para higienização e a conta seguiu para o faturamento.`)}
function clTransferir(id){const livres=CL_LEITOS.filter(l=>l.sit==='livre');if(!livres.length){toast('Nenhum leito livre para transferir','warn');return}modalOk('Transferir de leito',`<div class="field"><label>Para o leito</label><select class="in" id="trLeito">${livres.map(l=>`<option>${l.id}</option>`).join('')}</select></div><div class="field"><label>Motivo</label><input class="in" value="Pedido do paciente (apartamento)"></div>`,'Transferir',`clTransferirOk('${id}')`)}
function clTransferirOk(id){const de=CL_LEITOS.find(x=>x.id===id),para=CL_LEITOS.find(x=>x.id===(document.getElementById('trLeito')||{}).value)||CL_LEITOS.find(x=>x.sit==='livre');if(!para)return;const {pac,adm,med,diag,conv,prev,alerta}=de;Object.assign(para,{sit:'ocupado',pac,adm,med,diag,conv,prev,alerta});Object.assign(de,{sit:'higienizacao',desde:hhmm(new Date()),pac:'',alerta:''});closeDrawer();reView();toast(`Transferido para o leito ${para.id}; o ${id} foi para higienização`)}
function clCenso(){const oc=CL_LEITOS.filter(l=>l.sit==='ocupado');openModal(`${mh('Censo do dia · 04/11')}<div class="mb">${tabela(['Leito','Paciente','Dias','Médico','Diagnóstico','Convênio'],oc.map(l=>`<tr>${td('Leito',l.id)}${td('Paciente',esc(l.pac))}${td('Dias',clDias(l.adm))}${td('Médico',esc((PROF(l.med)||{}).n||''))}${td('Diagnóstico',esc(l.diag))}${td('Convênio',esc(l.conv))}</tr>`))}<p class="tl" style="margin-top:8px">Média de permanência: ${(oc.reduce((s,l)=>s+clDias(l.adm),0)/Math.max(1,oc.length)).toFixed(1).replace('.',',')} dias.</p></div><div class="mf"><button class="btn sec" onclick="toast('Censo exportado em PDF')">Exportar</button><button class="btn" onclick="closeModal()">Fechar</button></div>`,'wide')}
