Object.assign(DICAS,{
 medico:[['Pausa entre consultas','Dois minutos de pé entre um paciente e outro: alongue o pescoço e beba água. A próxima consulta agradece.'],['Tela na altura dos olhos','Prontuário aberto o dia todo pede monitor a um braço, topo na linha dos olhos.'],['Mãos lavadas, mente limpa','Lavar as mãos entre pacientes é também um respiro de 20 segundos.']],
 enfermagem:[['Costas na triagem','Ajuste a cadeira para aferir a pressão com o braço do paciente na altura do coração, sem curvar as suas costas.'],['Hidratação no plantão','Garrafa de água à vista: a enfermagem cuida de todo mundo e esquece de si.'],['Perfurocortante','Agulha direto no descartador, sem reencapar. Sem exceção, sem pressa.']],
 imagem:[['Postura no exame','Altura da maca no nível do cotovelo e o braço apoiado: ultrassom é esporte de repetição.'],['Pausa visual','A cada laudo, olhe por 20 segundos algo distante. A sala escura cansa a vista.'],['Punho neutro','Alterne a mão do transdutor quando der e solte o ombro entre um exame e outro.']],
 estoque:[['Carga com as pernas','Caixa pesada se levanta com as pernas, perto do corpo. A coluna não tem reposição.'],['Escada, não cadeira','Para a prateleira alta, use a escada. A cadeira com rodinha não é equipamento de estoque.'],['Luz no almoxarifado','Boa iluminação evita erro de lote e de validade, e poupa os olhos.']],
 faturamento:[['Uma guia por vez','Glosa nasce de pressa. Pausa curta a cada lote fechado.'],['Punhos apoiados','Teclado baixo e mouse perto do corpo: o lote é longo.'],['Olhos na distância','Regra 20-20-20 entre um XML e outro.']]});
Object.assign(PIADAS,{medico:'Médico: o único profissional que escreve "nada digno de nota" e é levado a sério.',enfermagem:'Enfermagem: quem mede a pressão de todo mundo e mantém a própria em 12 por 8 por pura força de vontade.',imagem:'Médico de imagem: vê por dentro o que o paciente jurou que era "só uma dorzinha".',estoque:'Estoque: o único setor em que sobra é problema e falta é tragédia.',faturamento:'Faturamento: a arte de transformar um procedimento em código, e o código em dinheiro, antes da glosa.'});
